/**
 * Determines whether a given remote resource, identified by its source URL,
 * is allowed based on specified domains and remote patterns.
 *
 * @param {string} src - The source URL of the remote resource to be validated.
 * @param {Object} options - The configuration options for domain and pattern matching.
 * @param {string[]} options.domains - A list of allowed domain names.
 * @param {RemotePattern[]} options.remotePatterns - A list of allowed remote patterns for matching.
 * @return {boolean} Returns `true` if the source URL matches any of the specified domains or remote patterns; otherwise, `false`.
 */
export function isRemoteAllowed(
	src: string,
	{
		domains,
		remotePatterns,
	}: {
		domains: string[];
		remotePatterns: RemotePattern[];
	},
): boolean {
	if (!URL.canParse(src)) {
		return false;
	}

	const url = new URL(src);

	// Non-http(s) protocols are never allowed
	if (!['http:', 'https:', 'data:'].includes(url.protocol)) {
		return false;
	}

	return (
		domains.some((domain) => matchHostname(url, domain)) ||
		remotePatterns.some((remotePattern) => matchPattern(url, remotePattern))
	);
}

/**
 * Fetches an image by URL. Used by the generic image endpoint for both
 * remote images and local images (self-fetched from the same origin).
 *
 * For remote images, the final URL (after any redirects) is validated
 * against `imageConfig.domains` and `imageConfig.remotePatterns`.
 * Local images skip this check — they are already guarded by the
 * same-origin check in the caller.
 */
export async function loadImage(
	src: URL,
	headers: Headers,
	imageConfig: RemoteImageConfig,
	isRemote: boolean,
	fetchFn?: typeof globalThis.fetch,
): Promise<ArrayBuffer | undefined> {
	try {
		const res = await fetchWithRedirects({ url: src, headers, imageConfig, fetchFn });

		if (isRemote && !isRemoteAllowed(res.url, imageConfig)) {
			return undefined;
		}

		if (!res.ok) {
			return undefined;
		}

		return await res.arrayBuffer();
	} catch {
		return undefined;
	}
}

export async function loadRemoteImage(src: URL): Promise<Buffer | undefined> {
	try {
		const res = await fetchWithRedirects({ url: src, imageConfig });

		// Local URLs are allowed by default
		if (!isRemoteAllowed(res.url, imageConfig) && !isLocal(res.url)) {
			return undefined;
		}

		if (!res.ok) {
			return undefined;
		}

		return Buffer.from(await res.arrayBuffer());
	} catch {
		return undefined;
	}
}

export type LocalImageLoadResult =
	| { kind: 'loaded'; buffer: Buffer }
	| { kind: 'invalid-path' }
	| { kind: 'not-found' }
	| { kind: 'failed' };

